"""
Discard Hold'em bot (Pokerbots 2026).

Plays by Monte Carlo equity against a weighted opponent range, with a time
budget on every decision and fallbacks so that it always answers legally.
Standard library only.
"""
import sys
import json
import time
import random

RANKS = "23456789TJQKA"
SUITS = "shdc"
CARD_INDEX = {r + s: i * 4 + j for i, r in enumerate(RANKS) for j, s in enumerate(SUITS)}
INDEX_CARD = {v: k for k, v in CARD_INDEX.items()}

# Strategy knobs (equity thresholds and frequencies).
P = {
    "btn_open": 0.54, "btn_call": 0.43, "pf_3bet": 0.70, "pf_margin": 0.04, "bb_raise": 0.58,
    "value_bet": 0.62, "value_raise": 0.80, "call_margin": 0.06, "bluff": 0.10, "semi": 0.25,
    "realize": 0.85, "ev_mode": 1, "reraise_p": 2.0, "callraise_p": 0.3, "learn_k": 3.0,
}

# ------------------------------------------------------------------ evaluator
# Card = rank * 4 + suit, rank 0 (two) .. 12 (ace).
# Score = category << 20 | tie-break bits; higher is better.

POP = [bin(m).count("1") for m in range(8192)]
RD = [[r for r in range(12, -1, -1) if m >> r & 1] for m in range(8192)]
STRAIGHT = [-1] * 8192
for _m in range(8192):
    for _top in range(12, 3, -1):
        _need = 0b11111 << (_top - 4)
        if _m & _need == _need:
            STRAIGHT[_m] = _top
            break
    else:
        if _m & 0b1000000001111 == 0b1000000001111:
            STRAIGHT[_m] = 3  # wheel, five-high


def _kick(ranks):
    v = 0
    for r in ranks:
        v = (v << 4) | r
    return v


TOP5 = [_kick(RD[m][:5]) for m in range(8192)]


def ev(cards):
    """Score of the best 5-card hand among 5 to 7 cards."""
    rc = [0] * 13
    sm = [0, 0, 0, 0]
    for c in cards:
        r = c >> 2
        rc[r] += 1
        sm[c & 3] |= 1 << r
    fl = 0
    for m in sm:
        if POP[m] >= 5:
            s = STRAIGHT[m]
            if s >= 0:
                return (8 << 20) | s
            fl = m
            break
    rm = sm[0] | sm[1] | sm[2] | sm[3]
    q = -1
    t = -1
    pairs = []
    for r in RD[rm]:
        n = rc[r]
        if n == 1:
            continue
        if n == 4:
            q = r
        elif n == 3:
            if t < 0:
                t = r
            else:
                pairs.append(r)
        else:
            pairs.append(r)
    if q >= 0:
        return (7 << 20) | (q << 4) | RD[rm & ~(1 << q)][0]
    if t >= 0 and pairs:
        return (6 << 20) | (t << 4) | pairs[0]
    if fl:
        return (5 << 20) | TOP5[fl]
    s = STRAIGHT[rm]
    if s >= 0:
        return (4 << 20) | s
    if t >= 0:
        return (3 << 20) | (t << 8) | _kick(RD[rm & ~(1 << t)][:2])
    if len(pairs) >= 2:
        a, b = pairs[0], pairs[1]
        return (2 << 20) | (a << 8) | (b << 4) | RD[rm & ~(1 << a) & ~(1 << b)][0]
    if pairs:
        a = pairs[0]
        return (1 << 20) | (a << 12) | _kick(RD[rm & ~(1 << a)][:3])
    return TOP5[rm]


def best_of(hole, board):
    """Best score using 2 hole cards (or the best 2 of 3) plus a full board."""
    if len(hole) == 2:
        return ev(hole + board)
    a, b, c = hole
    x = ev([a, b] + board)
    y = ev([a, c] + board)
    z = ev([b, c] + board)
    return x if x >= y and x >= z else (y if y >= z else z)


