def canon3(cards):
    cs = sorted(cards, key=lambda c: (-(c >> 2), c & 3))
    m = {}
    key = ""
    for c in cs:
        su = c & 3
        if su not in m:
            m[su] = len(m)
        key += "%x%d" % (c >> 2, m[su])
    return key


PREFLOP = {}
for _item in PREFLOP_TABLE.split(";"):
    _k, _v = _item.split(":")
    PREFLOP[_k] = [int(x) / 1000.0 for x in _v.split(",")]


# ------------------------------------------------------------- hand strength

def preflop_strength(hole):
    """Rough 0..1 strength of a 2 or 3 card hand with no board (fast proxy)."""
    rs = sorted((c >> 2 for c in hole), reverse=True)
    s = 0.10 + 0.40 * (rs[0] + rs[1]) / 24.0
    if len(set(rs)) < len(rs):
        pr = max(r for r in rs if rs.count(r) > 1)
        s += 0.25 + 0.15 * pr / 12.0
    suits = [c & 3 for c in hole]
    if len(set(suits)) < len(suits):
        s += 0.05
    if len(rs) >= 2 and (rs[0] - rs[1] == 1 or (len(rs) == 3 and rs[1] - rs[2] == 1)):
        s += 0.04
    return min(1.0, max(0.05, s))


def made_strength(hole, board):
    """Rough 0..1 strength of hole+board right now, with a draw bonus."""
    sc = ev(hole + board)
    cat = sc >> 20
    brs = sorted((c >> 2 for c in board), reverse=True)
    if cat == 0:
        s = 0.10 + 0.08 * (max(c >> 2 for c in hole) == 12)
    elif cat == 1:
        pr = (sc >> 12) & 15
        if pr in brs and sum(1 for c in hole if c >> 2 == pr) == 0:
            s = 0.15  # the pair is on the board
        elif pr >= brs[0]:
            s = 0.62
        elif len(brs) > 1 and pr >= brs[1]:
            s = 0.42
        else:
            s = 0.30
    elif cat == 2:
        s = 0.72
    elif cat == 3:
        s = 0.85
    else:
        s = 0.95
    if len(board) < 5 and s < 0.6:
        cnt = [0, 0, 0, 0]
        for c in board:
            cnt[c & 3] += 1
        for c in hole:
            if cnt[c & 3] + sum(1 for d in hole if d & 3 == c & 3) >= 4:
                s = max(s, 0.45)
                break
        rm = 0
        for c in hole + board:
            rm |= 1 << (c >> 2)
        for top in range(12, 2, -1):
            win = 0b11111 << (top - 4) if top >= 4 else 0
            if win and POP[rm & win] >= 4:
                s = max(s, 0.38)
                break
    return s


def keep_value(pair, flop):
    return ev(pair + flop) >> 20


def replay(hist):
    """Yield (index, street, actor, action, amount, size) for each action, where size is a
    bet or raise's increment as a fraction of the pot it was made into (None otherwise)."""
    pot = 0.0
    street = None
    level = {"me": 0, "opp": 0}
    out = []
    for i, h in enumerate(hist):
        st = h.get("street")
        if st != street:
            if street is None:
                pot = 3.0 if st == "preflop" else 4.0
                level = {"me": 1, "opp": 2} if st == "preflop" else {"me": 0, "opp": 0}
            else:
                pot = pot  # pot already includes everything committed
                level = {"me": 0, "opp": 0}
            street = st
        actor = h.get("actor")
        other = "me" if actor == "opp" else "opp"
        act = h.get("action")
        amt = h.get("amount") or 0
        size = None
        if act == "raise":
            facing = max(0, level[other] - level[actor])
            base = pot + facing
            size = (amt - level[other]) / base if base > 0 else 1.0
            pot += amt - level[actor]
            level[actor] = amt
        elif act == "call":
            pot += max(0, amt - level[actor])
            level[actor] = amt
        out.append((i, st, actor, act, amt, size))
    return out


def size_bucket(size):
    return 0 if size < 0.45 else (1 if size < 0.9 else 2)


# How the average "made strength" of a hand range grows as the range is narrowed
# with weight s**p (used to turn observed showdown strength into a pressure value).
_rs = random.Random(7)
_S = []
for _i in range(900):
    _cards = _rs.sample(range(52), 2 + 3 + _i % 3)
    _S.append(made_strength(_cards[:2], _cards[2:]))
P_GRID = [x / 10.0 for x in range(0, 81)]
F_GRID = [sum(v ** (p + 1) for v in _S) / sum(v ** p for v in _S) for p in P_GRID]


def strength_of_pressure(p):
    i = min(len(P_GRID) - 1, max(0, int(round(p * 10))))
    return F_GRID[i]


def pressure_of_strength(m):
    for p, f in zip(P_GRID, F_GRID):
        if f >= m:
            return p
    return P_GRID[-1]


# ------------------------------------------------------------ Monte Carlo

def equity(my, board, dead, opp_n, budget_s, max_sims=4000, min_sims=24, wfn=None):
    known = set(my) | set(board) | set(dead)
    rest = [c for c in range(52) if c not in known]
    need = 5 - len(board)
    k = opp_n + need
    sample = random.sample
    t_end = time.perf_counter() + budget_s
    my_fixed = best_of(my, board) if need == 0 else None
    tot = 0.0
    wsum = 0.0
    n = 0
    while n < max_sims:
        if (n & 7) == 0 and n >= min_sims and time.perf_counter() > t_end:
            break
        n += 1
        s = sample(rest, k)
        opp = s[:opp_n]
        w = wfn(opp) if wfn is not None else 1.0
        if w <= 0.0:
            continue
        full = board + s[opp_n:] if need else board
        ms = my_fixed if my_fixed is not None else best_of(my, full)
        os_ = best_of(opp, full)
        if ms > os_:
            tot += w
        elif ms == os_:
            tot += 0.5 * w
        wsum += w
    return tot / wsum if wsum > 0 else 0.5


def discard_choice(hole, flop, budget_s, opp_n=3):
    """Return the hole card whose removal leaves the best equity."""
    pairs = [([hole[1], hole[2]], hole[0]), ([hole[0], hole[2]], hole[1]), ([hole[0], hole[1]], hole[2])]
    known = set(hole) | set(flop)
    rest = [c for c in range(52) if c not in known]
    k = opp_n + 2
    tot = [0.0, 0.0, 0.0]
    n = 0
    t_end = time.perf_counter() + budget_s
    sample = random.sample
    while n < 3000:
        if (n & 7) == 0 and n >= 40 and time.perf_counter() > t_end:
            break
        n += 1
        s = sample(rest, k)
        opp = s[:opp_n]
        full = flop + s[opp_n:]
        os_ = best_of(opp, full)
        for i in range(3):
            ms = ev(pairs[i][0] + full)
            if ms > os_:
                tot[i] += 1.0
            elif ms == os_:
                tot[i] += 0.5
    best = max(range(3), key=lambda i: (tot[i], -(pairs[i][1] >> 2)))
    return pairs[best][1], [t / max(n, 1) for t in tot]


# ---------------------------------------------------------- opponent model

class OppModel:
    def __init__(self):
        self.actions = 8.0
        self.raises = 2.0
        self.faced = 8.0      # times opp faced our bet/raise
        self.folds = 3.0      # times opp folded to it
        self.faced_rr = 6.0   # times opp faced our raise after they had bet/raised on that street
        self.folds_rr = 1.2   # times they folded to it
        self.big_bets_shown = 6.0
        self.bluffs_shown = 1.5
        self.hands = 0
        # (street, size bucket or 3 for a re-raise) -> [sum of shown strength, count]
        self.bet_obs = {}

    @property
    def raise_rate(self):
        return self.raises / self.actions

    @property
    def fold_rate(self):
        return self.folds / self.faced

    @property
    def fold_rr_rate(self):
        return self.folds_rr / self.faced_rr

    @property
    def bluff_rate(self):
        return self.bluffs_shown / self.big_bets_shown

    def learn_bets(self, hist, msg):
        opp = [CARD_INDEX[c] for c in msg["opp_hole_cards"]]
        board = [CARD_INDEX[c] for c in msg["board"]]
        n_board = {"flop": 3, "turn": 4, "river": 5}
        raised = {}
        for i, st, actor, act, amt, size in replay(hist):
            if act != "raise":
                continue
            prior = raised.get(st, 0)
            raised[st] = prior + 1
            if actor != "opp" or st not in n_board or len(board) < n_board[st]:
                continue
            b = 3 if prior >= 1 else size_bucket(size)
            stg = made_strength(opp, board[:n_board[st]])
            o = self.bet_obs.setdefault((st, b), [0.0, 0])
            o[0] += stg
            o[1] += 1

    def update(self, msg):
        self.hands += 1
        hist = msg.get("history") or []
        last_me_raise = False
        last_me_rr = False
        opp_raised_on = set()
        for h in hist:
            actor = h.get("actor")
            act = h.get("action")
            st = h.get("street")
            if actor == "opp":
                self.actions += 1
                if act == "raise":
                    self.raises += 1
                    opp_raised_on.add(st)
                if last_me_raise:
                    self.faced += 1
                    if act == "fold":
                        self.folds += 1
                if last_me_rr:
                    self.faced_rr += 1
                    if act == "fold":
                        self.folds_rr += 1
                last_me_raise = False
                last_me_rr = False
            else:
                last_me_raise = act == "raise"
                last_me_rr = act == "raise" and st in opp_raised_on
        if msg.get("result") == "showdown" and msg.get("opp_hole_cards"):
            try:
                self.learn_bets(hist, msg)
            except Exception:
                pass
            opp_late_raise = any(h.get("actor") == "opp" and h.get("action") == "raise"
                                 and h.get("street") in ("turn", "river") for h in hist)
            if opp_late_raise:
                try:
                    opp = [CARD_INDEX[c] for c in msg["opp_hole_cards"]]
                    board = [CARD_INDEX[c] for c in msg["board"]]
                    if len(board) == 5:
                        self.big_bets_shown += 1
                        if made_strength(opp, board) <= 0.30:
                            self.bluffs_shown += 1
                except Exception:
                    pass


# ------------------------------------------------------------------- bot

class Bot:
    def __init__(self):
        self.total_hands = 400
        self.time_bank_ms = 60000
        self.hand_id = 0
        self.hole = []
        self.opp_discard = None
        self.flop = []
        self.opp = OppModel()
        self.pf_cache = {}

    # ---- time
    def budget(self, req, mult=1.0):
        left = req.get("time_left_ms", self.time_bank_ms)
        hands_left = max(1, self.total_hands - self.hand_id + 1)
        # Target about 35% of the bank over the match (~6 budget units per hand:
        # ~4 actions plus a discard worth 2.5). Never more than the fair share of what is left.
        fixed = self.time_bank_ms * 0.55 / (max(1, self.total_hands) * 6.0)
        ms = min(fixed, left * 0.55 / (hands_left * 6.0))
        if left < 0.15 * self.time_bank_ms or left < 4000:
            ms = min(ms, 1.0)
        ms = max(0.5, min(150.0, ms * mult))
        return ms / 1000.0

    # ---- messages
    def on_message(self, msg):
        t = msg.get("type")
        if t == "init":
            self.total_hands = int(msg.get("total_hands", 400))
            self.time_bank_ms = int(msg.get("time_bank_ms", 60000))
        elif t == "new_hand":
            self.hand_id = int(msg.get("hand_id", self.hand_id + 1))
            self.hole = [CARD_INDEX[c] for c in msg.get("hole_cards", [])]
            self.opp_discard = None
            self.flop = []
        elif t == "discard_result":
            hc = msg.get("hole_cards")
            if hc:
                self.hole = [CARD_INDEX[c] for c in hc]
            od = msg.get("opp_discard")
            self.opp_discard = CARD_INDEX.get(od) if od else None
        elif t == "hand_result":
            self.opp.update(msg)
        return None

    # ---- opponent range weighting
    def pressure(self, req):
        """How strongly the opponent's actions this hand narrow their range.

        Older actions use fixed weights. The opponent's latest bet or raise on the current
        street is read through what this opponent has shown down after bets of that size.
        """
        street = req.get("street")
        hist = req.get("history") or []
        p_disc = 0.0
        p_full = 0.0
        raised_on = {}
        cur_bet = None  # (bucket, default pressure) of opp's latest raise this street
        f = (0.25 / max(0.05, self.opp.raise_rate)) ** 0.7
        f = min(1.6, max(0.35, f))
        honest = (0.25 / max(0.05, self.opp.bluff_rate)) ** 0.5
        f *= min(1.6, max(0.7, honest))
        for i, st, actor, act, amt, size in replay(hist):
            if act == "raise":
                earlier = raised_on.get(st, 0) + (1 if st == "preflop" else 0)
                raised_on[st] = raised_on.get(st, 0) + 1
                if actor != "opp":
                    continue
                cur = st == street
                rr = earlier >= (2 if st == "preflop" else 1)
                if cur and st != "preflop":
                    if cur_bet is not None:  # an earlier opp raise this street: fixed weight
                        p_full += cur_bet[1]
                    dflt = P["reraise_p"] if rr else (0.8 + 0.35 * min(2.0, size or 0.0)) * f
                    cur_bet = (3 if rr else size_bucket(size or 0.0), dflt)
                elif rr:
                    p_full += P["reraise_p"] if cur else 0.6
                else:
                    p_disc += 0.8 if cur else 0.45
            elif act == "call" and actor == "opp":
                if raised_on.get(st, 0) >= 1 and st != "preflop":
                    p_full += P["callraise_p"] if st == street else P["callraise_p"] * 0.7
                else:
                    p_disc += 0.15
        if street == "preflop":
            to_call = req.get("to_call", 0)
            pot = req.get("pot", 0)
            if to_call > 0 and pot - to_call > 0:
                p_disc += 0.35 * min(2.0, to_call / float(pot - to_call))
        total = p_disc * f + p_full
        if cur_bet is not None:
            b, dflt = cur_bet
            m0 = strength_of_pressure(dflt)
            o = self.opp.bet_obs.get((street, b))
            k = P["learn_k"]
            if o:
                m = (o[0] + m0 * k) / (o[1] + k)
                total += pressure_of_strength(m)
            else:
                total += dflt
        return min(5.0, total)

    def street_raises(self, req):
        street = req.get("street")
        return sum(1 for h in req.get("history") or [] if h.get("street") == street and h.get("action") == "raise")

    def make_wfn(self, board, pressure):
        od = self.opp_discard
        flop = self.flop
        use_disc = od is not None and len(flop) == 3
        if pressure < 0.05 and not use_disc:
            return None

        def wfn(opp):
            w = 1.0
            if pressure >= 0.05:
                s = made_strength(opp, board) if board else preflop_strength(opp)
                w = s ** pressure
            if use_disc and len(opp) == 2:
                kept = keep_value(opp, flop)
                alt = max(keep_value([opp[0], od], flop), keep_value([opp[1], od], flop))
                if alt > kept:
                    w *= 0.35
            return w
        return wfn

    # ---- decisions
    def choose_discard(self, req):
        hole = [CARD_INDEX[c] for c in req["hole_cards"]]
        flop = [CARD_INDEX[c] for c in req["board"]]
        self.hole = hole
        self.flop = flop
        card, _ = discard_choice(hole, flop, self.budget(req, 2.5))
        return {"type": "discard", "card": INDEX_CARD[card]}

    def hand_equity(self, req):
        board = [CARD_INDEX[c] for c in req.get("board", [])]
        if len(board) >= 3 and not self.flop:
            self.flop = board[:3]
        hole = self.hole
        dead = [self.opp_discard] if self.opp_discard is not None else []
        if len(hole) == 3 and len(board) < 3:
            opp_n = 3
        elif len(hole) == 3:
            opp_n = 3
        else:
            opp_n = 2
        p = self.pressure(req)
        budget = self.budget(req)
        if not board and len(hole) == 3:
            e = self.preflop_equity(hole, req)
            if e is not None:
                return e
        if not board and p < 0.05:
            key = tuple(sorted(hole))
            if key not in self.pf_cache:
                self.pf_cache[key] = equity(hole, [], dead, opp_n, budget)
            return self.pf_cache[key]
        return equity(hole, board, dead, opp_n, budget, wfn=self.make_wfn(board, p))

    def preflop_equity(self, hole, req):
        """Equity from the precomputed table, against the range the opponent's raises suggest."""
        row = PREFLOP.get(canon3(hole))
        if row is None:
            return None
        n_or = sum(1 for h in req.get("history") or []
                   if h.get("street") == "preflop" and h.get("actor") == "opp" and h.get("action") == "raise")
        agg = (0.25 / max(0.05, self.opp.raise_rate)) ** 0.5
        level = min(3.0, n_or * min(1.2, max(0.5, agg)))
        i = int(level)
        if i >= 3:
            return row[3]
        frac = level - i
        return row[i] * (1 - frac) + row[i + 1] * frac

    def choose_action(self, req):
        legal = req.get("legal_actions", [])
        street = req.get("street", "preflop")
        to_call = req.get("to_call", 0)
        pot = req.get("pot", 0)
        opp_bet = req.get("opp_bet", 0)
        can_raise = "raise" in legal and "min_raise" in req and "max_raise" in req
        lo = req.get("min_raise", 0)
        hi = req.get("max_raise", 0)

        def act(a):
            return {"type": "action", "action": a}

        def raise_to(amount):
            amount = int(max(lo, min(hi, int(amount))))
            if amount >= 0.7 * hi:
                amount = hi
            return {"type": "action", "action": "raise", "amount": amount}

        def passive():
            return act("check") if "check" in legal else act("fold")

        if len(self.hole) not in (2, 3):
            return act("check") if "check" in legal else (act("call") if to_call <= 2 and "call" in legal else act("fold"))

        e = self.hand_equity(req)
        rnd = random.random()
        om = self.opp

        if street == "preflop":
            if to_call > 0:
                odds = to_call / float(pot + to_call)
                if req.get("my_bet", 0) <= 1 and to_call == 1:  # button, first action
                    if can_raise and e > P['btn_open'] + 0.06 * rnd:
                        return raise_to(6)
                    if e > P['btn_call'] and "call" in legal:
                        return act("call")
                    return act("fold")
                if can_raise and e > P['pf_3bet'] and req.get("raises_left", 0) > 0:
                    if e > 0.80 and rnd < 0.5:
                        return raise_to(hi)
                    return raise_to(opp_bet * 3)
                margin = P['pf_margin'] - (om.bluff_rate - 0.2) * 0.25
                if e > odds + margin and "call" in legal:
                    return act("call")
                return act("fold")
            # big blind option after a limp
            if can_raise and e > P['bb_raise']:
                return raise_to(8)
            return act("check")

        # postflop: pick the move with the best expected chips.
        if P.get("ev_mode", 1):
            return self.ev_postflop(req, e, act, raise_to, can_raise, lo, hi)
        if to_call > 0:
            odds = to_call / float(pot + to_call)
            if can_raise and req.get("raises_left", 0) > 0 and e > P['value_raise']:
                return raise_to(opp_bet + 0.8 * (pot + to_call))
            margin = P['call_margin'] - (om.bluff_rate - 0.2) * 0.3
            if street == "river":
                margin += 0.02
            if e > odds + margin and "call" in legal:
                return act("call")
            return act("fold") if "fold" in legal else passive()

        if not can_raise:
            return act("check")
        if e > P['value_bet']:
            frac = 0.5 + 0.45 * min(1.0, (e - P['value_bet']) / 0.3)
            return raise_to(pot * frac)
        bluff_p = P['bluff'] * min(2.5, om.fold_rate / 0.4)
        if street == "river":
            bluff_p *= 0.8
        if e < 0.40 and rnd < bluff_p:
            return raise_to(pot * 0.6)
        if 0.45 < e <= P['value_bet'] and street != "river" and rnd < P['semi']:
            return raise_to(pot * 0.5)
        return act("check")

    def ev_postflop(self, req, e, act, raise_to, can_raise, lo, hi):
        """Expected-chips choice between fold/check/call and a few raise sizes."""
        legal = req.get("legal_actions", [])
        street = req.get("street")
        pot = float(req.get("pot", 0))
        to_call = req.get("to_call", 0)
        my_bet = req.get("my_bet", 0)
        opp_bet = req.get("opp_bet", 0)
        om = self.opp
        river = street == "river"
        # How much of our equity we actually realise if we just check/call.
        real = 1.0 if river else P["realize"]
        # Equity against the hands that fold: they are mostly weak.
        e_fold = 0.85 if river else 0.72

        options = []
        if to_call > 0:
            margin = P['call_margin'] - (om.bluff_rate - 0.2) * 0.3 + (0.02 if river else 0.0)
            ev_call = (e - margin) * real * (pot + to_call) - to_call
            options.append((ev_call, "call"))
            options.append((0.0, "fold"))
            nr = self.street_raises(req)
            base_fold = om.fold_rr_rate * (1.0 if nr <= 1 else 0.5)  # measured fold rate to our re-raises
        else:
            options.append((e * real * pot, "check"))
            base_fold = om.fold_rate
        if can_raise and req.get("raises_left", 0) > 0:
            seen = set()
            for frac in (0.4, 0.7, 1.1):
                target = int(max(lo, min(hi, opp_bet + frac * (pot + to_call))))
                if target >= 0.7 * hi:
                    target = hi
                if target in seen:
                    continue
                seen.add(target)
                add_me = target - my_bet
                add_opp = target - opp_bet
                size = add_opp / max(1.0, pot + to_call)
                f = base_fold * min(1.4, 0.75 + 0.45 * size)
                f = max(0.0, min(0.85, f))
                e_c = (e - f * e_fold) / (1.0 - f) if f < 1 else e
                e_c = max(0.02, min(e, e_c))
                if to_call > 0 and self.street_raises(req) >= 2 and e_c < 0.55:
                    continue  # never escalate a raising war without a strong hand
                ev = f * pot + (1 - f) * (e_c * (pot + add_me + add_opp) - add_me)
                options.append((ev, ("raise", target)))
        options.sort(key=lambda o: o[0], reverse=True)
        best = options[0][1]
        # Mix in a little unpredictability on close decisions.
        if len(options) > 1 and options[0][0] - options[1][0] < 0.03 * pot and random.random() < 0.25:
            best = options[1][1]
        if isinstance(best, tuple):
            return raise_to(best[1])
        if best == "call" and "call" in legal:
            return act("call")
        if best == "check" and "check" in legal:
            return act("check")
        if best == "fold" and "fold" in legal:
            return act("fold")
        return act("check") if "check" in legal else act("fold")


# ------------------------------------------------------------------ main

def safe_action(req):
    legal = req.get("legal_actions", []) if isinstance(req, dict) else []
    if "check" in legal:
        return {"type": "action", "action": "check"}
    if "call" in legal and req.get("to_call", 99) <= 4:
        return {"type": "action", "action": "call"}
    return {"type": "action", "action": "fold"}


def safe_discard(req):
    try:
        cards = req["hole_cards"]
        return {"type": "discard", "card": min(cards, key=lambda c: (RANKS.index(c[0]), SUITS.index(c[1])))}
    except Exception:
        return {"type": "discard", "card": "2s"}


def valid_action(reply, req):
    try:
        a = reply.get("action")
        if a not in req.get("legal_actions", []):
            return False
        if a == "raise":
            amt = reply.get("amount")
            return isinstance(amt, int) and req["min_raise"] <= amt <= req["max_raise"]
        return True
    except Exception:
        return False


def main():
    bot = Bot()
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except Exception:
            continue
        if not isinstance(msg, dict):
            continue
        t = msg.get("type")
        reply = None
        if t == "action_request":
            try:
                reply = bot.choose_action(msg)
                if not valid_action(reply, msg):
                    reply = safe_action(msg)
            except Exception as exc:
                print("action error: %r" % (exc,), file=sys.stderr)
                reply = safe_action(msg)
        elif t == "discard_request":
            try:
                reply = bot.choose_discard(msg)
                if reply.get("card") not in msg.get("hole_cards", []):
                    reply = safe_discard(msg)
            except Exception as exc:
                print("discard error: %r" % (exc,), file=sys.stderr)
                reply = safe_discard(msg)
        elif t == "match_end":
            break
        else:
            try:
                bot.on_message(msg)
            except Exception as exc:
                print("state error: %r" % (exc,), file=sys.stderr)
            continue
        try:
            out.write(json.dumps(reply) + "\n")
            out.flush()
        except Exception:
            return


if __name__ == "__main__":
    main()
